import json


def render(rows,path):
    data=json.dumps(rows).replace('<','\\u003c')
    path.write_text('''<!doctype html><meta charset="utf-8"><title>Antsy — API selection under deadline pressure</title><style>body{background:#101820;color:#e9f3ee;font:17px system-ui;margin:35px auto;padding:0 24px;box-sizing:border-box;max-width:1150px}select,input{font:inherit}svg{width:100%;height:350px}circle{fill:#2a7777}text{fill:white;font-size:17px}line{stroke:#55bbbb;stroke-width:2}table{border-collapse:collapse;width:100%}td,th{padding:9px;border-bottom:1px solid #365050;text-align:left}.badge{color:#ffce73}</style><h1>Antsy</h1><p>API selection under deadline pressure</p><p class="badge">Exploratory qualification · Local Laya or scripted backend · Synthetic supplier evidence</p><select id="pick"></select><input type="range" id="round" min="1" value="1"><p id="outcome"></p><svg viewBox="0 0 1150 350" id="graph"></svg><h2>Evidence available by this round</h2><table><thead><tr><th>Root/revision</th><th>Provider</th><th>Scanned PDFs</th><th>Retention days</th><th>Accuracy</th><th>Price</th></tr></thead><tbody id="facts"></tbody></table><script>const rows='''+data+''';const pick=document.querySelector('#pick'),slider=document.querySelector('#round');const team=rows.filter(r=>r.arm==='majority');team.forEach((r,i)=>{let o=document.createElement('option');o.value=i;o.textContent=`Task ${r.task_id} · ${r.agents} scouts · deadline ${r.deadline}`;pick.append(o)});function draw(){let r=team[+pick.value];slider.max=r.deadline;let t=Math.min(+slider.value,r.deadline),frame=r.trace[t-1],svg='';frame.votes.forEach((v,i)=>{let x=55+i*1040/(r.agents-1),j=['A','B','C','NONE','WAIT'].indexOf(v);svg+=`<line x1="${x}" y1="65" x2="${115+j*230}" y2="260"/><circle cx="${x}" cy="45" r="25"/><text x="${x}" y="51" text-anchor="middle">${i+1}</text>`});['A','B','C','NONE','WAIT'].forEach((v,i)=>svg+=`<circle cx="${115+i*230}" cy="270" r="42"/><text x="${115+i*230}" y="276" text-anchor="middle">${v}</text>`);document.querySelector('#graph').innerHTML=svg;document.querySelector('#outcome').textContent=`${r.backend} / round ${t}: `+rows.filter(x=>x.task_id===r.task_id&&x.agents===r.agents&&x.deadline===r.deadline).map(x=>`${x.arm}: ${x.choice??'WAIT'} (${x.evaluation.correct?'correct':'incorrect'})`).join(' · ');let body=document.querySelector('#facts');body.replaceChildren();r.documents.filter(d=>d.arrival<=t).forEach(d=>{let tr=document.createElement('tr');[d.root+'/'+d.revision,d.provider,d.facts.scanned,d.facts.retention_days,d.facts.accuracy,d.facts.price].forEach(v=>{let td=document.createElement('td');td.textContent=v;tr.append(td)});body.append(tr)})}pick.onchange=()=>{slider.value=1;draw()};slider.oninput=draw;draw();</script>''')
